<script lang="ts">
 import {goto} from '$app/navigation';import {app,run} from '../app.svelte';import {claimStore} from '../store';import {categories,statuses} from '../types';import {total,money} from '../money';import Icon from '../components/Icon.svelte';import ClaimsTable from '../components/ClaimsTable.svelte';
 const data=$derived(app.data!);const actor=$derived(data.users.find(u=>u.id===data.session?.userId)!);const claims=$derived(data.claims);const active=$derived(claims.filter(c=>!['Draft','Rejected','Cancelled'].includes(c.status)));const spent=$derived(total(active.flatMap(c=>c.lines),true));const pending=$derived(claims.filter(c=>['Submitted','Manager approved','Finance approved'].includes(c.status)));const paid=$derived(claims.filter(c=>c.status==='Paid'));const returned=$derived(claims.filter(c=>c.status==='Returned for correction'));
 const categoryRows=$derived(categories.map(category=>({name:category,value:total(active.flatMap(c=>c.lines.filter(l=>l.category===category)),true)})).filter(x=>x.value).sort((a,b)=>b.value-a.value));
 const departmentRows=$derived(['Engineering','Operations','Design'].map(name=>({name,value:total(active.filter(c=>c.department===name).flatMap(c=>c.lines),true)})));
 const months=$derived(Array.from({length:6},(_,i)=>{const date=new Date();date.setMonth(date.getMonth()-5+i);const key=date.toISOString().slice(0,7);return {name:date.toLocaleDateString('en-IN',{month:'short'}),value:total(active.flatMap(c=>c.lines.filter(l=>l.date.startsWith(key))),true)};}));
 const withFindings=$derived(claims.filter(c=>claimStore.findings(c).length).length);
 const approvalHours=$derived(data.audit.filter(a=>a.status==='Manager approved').map(a=>{const c=claims.find(c=>c.id===a.claimId);return c?.submittedAt?Math.max(0,(Date.parse(a.time)-Date.parse(c.submittedAt))/3600000):0;}));
 async function create(){const c=await run(()=>claimStore.create());if(c)goto('/claims/'+c.id);}
</script>
<div class="page-header"><div><p class="eyebrow">{actor.role==='Employee'?'YOUR EXPENSE WORKSPACE':'SPENDING AT A GLANCE'}</p><h1>{actor.role==='Employee'?`Hello, ${actor.name.split(' ')[0]}.`:'Expense dashboard'}</h1><p>{actor.role==='Employee'?'A clear view of your expenses, from claim to payment.':actor.role==='Manager'?'Your assigned team’s spend, approvals and policy health.':'A complete view of the claims stored in this browser.'}</p></div>{#if actor.role==='Employee'}<button class="primary" onclick={create}><Icon name="plus" size={18}/>New claim</button>{:else}<a class="button primary" href={actor.role==='Manager'?'/manager':'/finance'}>Review claims<Icon name="arrow" size={18}/></a>{/if}</div>
<div class="stats-grid"><div class="stat-card"><div><span>Total claimed</span><Icon name="claim"/></div><strong>{money(spent)}</strong><small>{active.length} active & completed claims</small></div><div class="stat-card"><div><span>Awaiting reimbursement</span><Icon name="clock"/></div><strong>{money(total(pending.flatMap(c=>c.lines),true))}</strong><small><span class="dot brand-dot"></span>{pending.length} claims in progress</small></div><div class="stat-card"><div><span>Reimbursed</span><Icon name="wallet"/></div><strong>{money(total(paid.flatMap(c=>c.lines),true))}</strong><small><span class="dot success-dot"></span>{paid.length} claims paid</small></div><div class="stat-card"><div><span>{actor.role==='Employee'?'Needs your attention':'Policy findings rate'}</span><Icon name="shield"/></div><strong>{actor.role==='Employee'?returned.length:claims.length?Math.round(withFindings/claims.length*100)+'%':'—'}</strong><small>{actor.role==='Employee'?'Returned for correction':'Claims with at least one finding'}</small></div></div>
{#if returned.length&&actor.role==='Employee'}<a class="attention-banner" href={'/claims/'+returned[0].id}><span class="attention-icon"><Icon name="return"/></span><div><strong>A little more detail is needed.</strong><p>{returned.length} returned claim{returned.length===1?' is':'s are'} ready for your correction. Your earlier history is kept.</p></div><Icon name="arrow"/></a>{/if}
<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Spend by category</h2><p>Active and completed claims · INR</p></div><span class="tag">All time</span></div><div class="category-chart">{#each categoryRows.slice(0,6) as row,i}<div class="bar-row"><div><span><span class="chart-key" style={`background:var(--chart-${i%4})`}></span>{row.name}</span><strong>{money(row.value)}</strong></div><svg viewBox="0 0 500 8" preserveAspectRatio="none" role="img" aria-label={`${row.name}: ${money(row.value)}`}><rect width="500" height="8" rx="4" fill="var(--subtle)"/><rect width={Math.max(2,row.value/Math.max(...categoryRows.map(r=>r.value),1)*500)} height="8" rx="4" fill={`var(--chart-${i%4})`}/></svg></div>{/each}{#if !categoryRows.length}<p class="empty-inline">Your spending summary appears after your first submission.</p>{/if}</div></section><section class="panel"><div class="panel-heading"><div><h2>Monthly spending</h2><p>Expense date · Last six months</p></div><Icon name="chart"/></div><div class="monthly-chart"><svg viewBox="0 0 420 180" role="img" aria-label="Monthly spending chart"><path d="M10 145H410 M10 100H410 M10 55H410" stroke="var(--border)" stroke-dasharray="4 4"/>{#each months as row,i}<rect x={22+i*68} y={145-row.value/Math.max(...months.map(r=>r.value),1)*115} width="30" height={Math.max(2,row.value/Math.max(...months.map(r=>r.value),1)*115)} rx="4" fill={i===5?'var(--brand)':'var(--chart-muted)'}><title>{row.name}: {money(row.value)}</title></rect><text x={37+i*68} y="170" text-anchor="middle" fill="var(--secondary)" font-size="12">{row.name}</text>{/each}</svg><div class="chart-summary"><span>{actor.role==='Employee'?'Your claims, not your colleagues’':'Average manager approval time'}</span><strong>{actor.role==='Employee'?'Private view':approvalHours.length?(approvalHours.reduce((a,b)=>a+b,0)/approvalHours.length).toFixed(1)+' hours':'No approvals yet'}</strong></div></div></section></div>
{#if actor.role!=='Employee'}<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Spend by department</h2></div><div class="category-chart">{#each departmentRows as row}<div class="bar-row"><div><span>{row.name}</span><strong>{money(row.value)}</strong></div><svg viewBox="0 0 500 8" preserveAspectRatio="none" role="img" aria-label={`${row.name}: ${money(row.value)}`}><rect width="500" height="8" rx="4" fill="var(--subtle)"/><rect width={row.value/Math.max(...departmentRows.map(r=>r.value),1)*500} height="8" rx="4" fill="var(--brand)"/></svg></div>{/each}</div></section><section class="panel"><div class="panel-heading"><h2>Claims by status</h2></div><div class="status-summary">{#each statuses as status}<div><span>{status}</span><strong>{claims.filter(c=>c.status===status).length}</strong></div>{/each}</div></section></div>{/if}
<section class="panel recent-panel"><div class="panel-heading"><div><h2>{actor.role==='Employee'?'Recent claims':'Largest claims'}</h2><p>{actor.role==='Employee'?'Your latest expenses and where they stand.':'Ordered by requested amount, highest first.'}</p></div><a class="text-link" href={actor.role==='Employee'?'/claims':actor.role==='Manager'?'/manager':'/finance'}>View all<Icon name="arrow" size={16}/></a></div><ClaimsTable claims={[...claims].sort((a,b)=>actor.role==='Employee'?b.updatedAt.localeCompare(a.updatedAt):total(b.lines)-total(a.lines)).slice(0,5)} users={data.users} team={actor.role!=='Employee'}/></section>